"""Requests & approvals: vacation (manager → director), permission hours (manager), rejection, cancel,
privacy (teammates see approved leave only), data-layer guards, acting manager, request types."""
from harness import app_session, Check, run, SHOTS
async def main():
    c = Check('requests & approvals')
    async with app_session() as s:
        pg = s.page
        thu = await s.js("(() => { let d = U.addDays(U.todayStr(), 7); while (U.pd(d).getDay() !== 4) d = U.addDays(d, 1); return d; })()")
        sun = await s.js(f"U.addDays('{thu}', 3)")
        async def new_request(type_id, frm, to='', hours='', reason='', leave='', title='', related=''):
            await s.go('#/home'); await s.go('#/requests/mine'); await pg.click('#newreq'); await pg.wait_for_selector('#rqf')
            await pg.select_option('#rqf [name=type]', type_id)
            if title: await pg.fill('#rqf [name=title]', title)
            if related: await pg.select_option('#rqf [name=related]', related)
            if leave: await pg.select_option('#rqf [name=leaveType]', leave)
            await pg.fill('#rqf [name=from]', frm)
            if to: await pg.fill('#rqf [name=to]', to)
            if hours: await pg.fill('#rqf [name=hours]', hours)
            if reason: await pg.fill('#rqf [name=reason]', reason)
            flow = await pg.inner_text('#rqflow'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
            if await pg.locator('#rqf').count(): await s.js('UI.closeModal()')   # refused: the form stays open
            return flow
        # 1 analyst asks for vacation
        await s.sign_in_as('yousef'); c('Requests in the menu', 'Requests' in await pg.inner_text('nav'))
        flow = await new_request('leave', thu, sun, reason='Family trip', leave='Annual')
        c('vacation flow: manager then director', 'your manager, then the director' in flow and 'Attendance' in flow, flow)
        rid = await s.js("Store.all('request', '*').find(r => r.reason === 'Family trip').id")
        c('request is Pending manager', await s.js(f"Store.get('{rid}').status") == 'Pending manager')
        c('2 working days (Thu + Sun, weekend skipped)', await s.js(f"Requests.days(Store.get('{rid}')).length") == 2)
        # guards
        await s.js(f"Store.save(Object.assign({{}}, Store.get('{rid}'), {{status: 'Approved'}}))")
        c('requester cannot approve own request', await s.js(f"Store.get('{rid}').status") == 'Pending manager')
        await s.sign_in_as('layla')
        await s.js(f"Store.save(Object.assign({{}}, Store.get('{rid}'), {{status: 'Approved'}}))")
        c('another analyst cannot approve it', await s.js(f"Store.get('{rid}').status") == 'Pending manager')
        t = await s.go('#/requests/leave'); c('teammate does not see pending leave', 'Qahtani' not in t)
        c('analyst has no "To approve" tab', 'To approve' not in await s.go('#/requests/mine'))
        # 2 manager approves (step 1)
        await s.sign_in_as('apps-mgr'); c('manager sees a count in the menu', await pg.locator('nav [data-nav="requests"] .count').count() == 1)
        t = await s.go('#/manager'); c('Manager Desk: "Waiting for your approval"', 'Waiting for your approval' in t and 'Family trip' in t)
        await pg.click(f'[data-rqok="{rid}"]'); await pg.wait_for_selector('#rqd'); note = await pg.inner_text('#modal')
        c('manager is told it goes to the director', 'go to the director' in note); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('now Pending director, attendance not yet written', await s.js(f"Store.get('{rid}').status") == 'Pending director' and await s.js(f"!Store.get('att-{thu}-yousef')"))
        # 3 director approves (final)
        await s.sign_in_as('khalid'); t = await s.go('#/home'); c('Director Desk shows it waiting', 'Waiting for your approval' in t and 'Approval' in t and 'Family trip' in t)
        await pg.click(f'[data-rqok="{rid}"]'); await pg.wait_for_selector('#rqd'); await pg.fill('#rqd [name=comment]', 'Enjoy'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('Completed', await s.js(f"Store.get('{rid}').status") == 'Completed')
        att = await s.js(f"[Store.get('att-{thu}-yousef'), Store.get('att-{sun}-yousef'), Store.get('att-' + U.addDays('{thu}', 1) + '-yousef')]")
        c('attendance OFF (Annual) on Thu and Sun, nothing on Friday', att[0] and att[0]['status'] == 'OFF' and att[0]['leave'] == 'Annual' and att[1] and att[1]['status'] == 'OFF' and att[2] is None, att)
        # 4 requester + teammates
        await s.sign_in_as('yousef'); t = await s.go('#/home'); c("My Day shows the decision with the director's comment", 'My requests' in t and 'Completed' in t and 'Enjoy' in t)
        await s.sign_in_as('layla'); t = await s.go('#/requests/leave')
        c('teammate sees the approved leave, not the reason', 'Yousef' in t and 'Family trip' not in t)
        # 5 permission hours: manager only, adds hours to attendance
        await s.sign_in_as('yousef'); await new_request('permission', thu, hours='2', reason='Overlap')
        c('permission on a day of approved leave is refused', await s.js("!Store.all('request', '*').some(r => r.reason === 'Overlap')"))
        await new_request('leave', sun, await s.js(f"U.addDays('{sun}', 2)"), reason='Overlap 2')
        c('overlapping leave is refused', await s.js("!Store.all('request', '*').some(r => r.reason === 'Overlap 2')"))
        mon = await s.js(f"U.addDays('{sun}', 1)")
        flow = await new_request('permission', mon, hours='2', reason='Clinic')
        c('permission flow: manager only', 'your manager' in flow and 'director' not in flow, flow)
        pid = await s.js("Store.all('request', '*').find(r => r.reason === 'Clinic').id")
        await s.sign_in_as('apps-mgr'); await s.go('#/requests/approve'); await pg.click(f'[data-rqok="{pid}"]'); await pg.wait_for_selector('#rqd'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('permission approved in one step', await s.js(f"Store.get('{pid}').status") == 'Completed')
        c('permission hours on that day', await s.js(f"Store.get('att-{mon}-yousef').permHrs") == 2)
        c('the leave days are untouched', await s.js(f"Store.get('att-{thu}-yousef').status") == 'OFF')
        # 6 reject needs a reason
        await s.sign_in_as('yousef'); await new_request('other', thu, reason='No subject')
        c('"Other approval" needs a subject', await s.js("!Store.all('request', '*').some(r => r.reason === 'No subject')"))
        await new_request('other', thu, reason='New monitor', title='Second monitor')
        oid = await s.js("Store.all('request', '*').find(r => r.reason === 'New monitor').id")
        await s.sign_in_as('apps-mgr'); await s.go('#/requests/approve'); await pg.click(f'[data-rqno="{oid}"]'); await pg.wait_for_selector('#rqd'); await pg.click('[data-ok]'); await pg.wait_for_timeout(200)
        c('rejecting without a reason is refused', await s.js(f"Store.get('{oid}').status") == 'Pending manager')
        await pg.fill('#rqd [name=comment]', 'Not in budget'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('rejected with reason', await s.js(f"(r => r.status === 'Rejected' && r.mgrComment === 'Not in budget')(Store.get('{oid}'))"))
        # 7 cancel own pending
        await s.sign_in_as('yousef'); await new_request('training', thu, sun, reason='Epic course')
        tid = await s.js("Store.all('request', '*').find(r => r.reason === 'Epic course').id")
        await s.go('#/requests/mine'); await pg.click(f'[data-rqx="{tid}"]'); await pg.wait_for_timeout(200); await pg.click('#modal .btn.primary, #modal [data-ok], #modal .btn.danger'); await pg.wait_for_timeout(300)
        c('requester cancels own pending request', await s.js(f"Store.get('{tid}').status") == 'Canceled')
        # 8 a manager's own request goes straight to the director
        await s.sign_in_as('apps-mgr'); flow = await new_request('permission', thu, hours='1', reason='Mgr errand')
        c("manager's own request goes to the director", await s.js("Store.all('request', '*').find(r => r.reason === 'Mgr errand').status") == 'Pending director' and 'director' in flow)
        # 9 acting manager approves while the manager is on leave
        await s.sign_in_as('adam'); await s.js("Store.save({id: 'settings-delegations', c: 'settings', list: [{from: 'apps-mgr', to: 'layla', start: U.todayStr(), end: U.addDays(U.todayStr(), 5)}]})"); await pg.wait_for_timeout(300)
        await s.sign_in_as('yousef'); await new_request('other', thu, reason='Badge renewal', title='Badge renewal')
        bid = await s.js("Store.all('request', '*').find(r => r.reason === 'Badge renewal').id")
        await s.sign_in_as('layla'); t = await s.go('#/manager')
        c('acting manager sees it waiting', 'Badge renewal' in t)
        await pg.click(f'[data-rqok="{bid}"]'); await pg.wait_for_selector('#rqd'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('acting manager can approve', await s.js(f"Store.get('{bid}').status") == 'Completed')
        await pg.screenshot(path=f'{SHOTS}/requests_acting.png', full_page=True)
        # 10 approval about a task, sent on to the director by the manager
        await s.sign_in_as('adam'); await s.js("Store.save({id: 'settings-delegations', c: 'settings', list: []})")
        await s.js("Store.save({c: 'todo', id: 'td-or', task: 'Build OR order set', analyst: 'yousef', assigned: U.todayStr(), duration: 5, status: 'In Progress'})"); await pg.wait_for_timeout(300)
        await s.sign_in_as('yousef'); await new_request('other', thu, title='Production access for OR order set', related='todo:td-or', reason='Needed to deploy')
        eid = await s.js("Store.all('request', '*').find(r => r.reason === 'Needed to deploy').id")
        c('request linked to the To Do', await s.js(f"Store.get('{eid}').related") == 'todo:td-or' and 'Build OR order set' in await s.go('#/requests/mine'))
        await s.sign_in_as('apps-mgr'); await s.go('#/requests/approve'); await pg.click(f'[data-rqok="{eid}"]'); await pg.wait_for_selector('#rqd')
        await pg.check('#rqd [name=escalate]'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('manager sends it on to the director', await s.js(f"(r => r.status === 'Pending director' && r.escalated)(Store.get('{eid}'))"))
        await s.sign_in_as('khalid'); await s.go('#/home'); await pg.click(f'[data-rqok="{eid}"]'); await pg.wait_for_selector('#rqd'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('director gives the final approval', await s.js(f"Store.get('{eid}').status") == 'Completed')
        # 11 directors approve but do not raise requests
        await s.sign_in_as('khalid'); t = await s.go('#/requests')
        c('director: no "My requests" tab, no New request', 'My requests' not in t and await pg.locator('#newreq').count() == 0 and 'Waiting for you' in t)
        await s.js("Store.save({c: 'request', type: 'other', title: 'x', requester: 'khalid', team: '_top', from: U.todayStr(), status: 'Pending manager'})")
        c('…and the data layer refuses one', await s.js("!Store.all('request', '*').some(r => r.requester === 'khalid')"))
        c('statuses say Completed, not Approved', 'Completed' in t and 'Approved<' not in await pg.inner_html('#main'))
        # 11 super admin changes request types
        await s.sign_in_as('adam'); await s.go('#/admin/teams')
        await pg.check('#rqtypes tr[data-rt="training"] [data-k="director"]'); await pg.click('#savert'); await pg.wait_for_timeout(300)
        c('admin makes Training need the director', await s.js("Requests.type('training').director") is True)
        await s.go('#/requests/approve'); await pg.screenshot(path=f'{SHOTS}/requests_all.png', full_page=True)
        c.done(s)
run(main())
